function statDetail(label,value){if(statsTab==='leetcode')dialog('LEETCODE / SOURCE SNAPSHOT',`<h2>${esc(label)} / ${value} solved</h2><p>${esc(lcProvenance())}</p><p>The complete total is ${profile.leetcode.solved} problems: ${profile.leetcode.easy} Easy, ${profile.leetcode.medium} Medium and ${profile.leetcode.hard} Hard.</p><div class="dialog-actions">${link('https://leetcode.com/u/ayushkathoke/','View current LeetCode profile')}</div>`);else{const repos=ownRepos().filter(r=>r.language===label);dialog('GITHUB / '+label.toUpperCase(),`<h2>${esc(label)}</h2><p>${value} owned, non-fork public repositories use ${esc(label)} as their primary language.</p><div class="dialog-actions">${repos.map(r=>link(r.html_url,r.name)).join('')}</div>`);}}
