function certificationType(c){const type=String(c.type||c.issuer||((c.asset||'').startsWith('nptel')?'nptel':(c.asset||'').startsWith('hr-')?'hr':'custom')).toLowerCase();if(type.includes('nptel'))return 'nptel';if(type==='hr'||type.includes('hackerrank'))return 'hr';return type.replace(/[^a-z0-9-]+/g,'-');}
function credentialIdentity(c){if(c.credentialId)return c.credentialId;try{const u=new URL(c.url);return (u.pathname.includes('/certificates/')?u.pathname.split('/').filter(Boolean).pop():u.searchParams.get('q'))||'See issuer';}catch{return 'See issuer';}}
function renderCerts(){
 const total=profile.certifications.length,nptelCount=profile.certifications.filter(c=>certificationType(c)==='nptel').length,hrCount=profile.certifications.filter(c=>certificationType(c)==='hr').length;
 $('.certification-header>.subline').textContent=total+' CERTIFICATES · PUBLIC ISSUER LINKS · SELECT A CARD TO VERIFY';
 const summary=$$('.cert-summary b');summary[0].textContent=nptelCount+' NPTEL COURSES';summary[1].textContent=(total-nptelCount)+' '+(total-nptelCount===hrCount?'HACKERRANK CERTS':'SKILL CREDENTIALS');
 $('.cert-summary>span:last-child>small').textContent=total-nptelCount===hrCount?'SKILL TESTS PASSED':'EXTERNAL ISSUING PLATFORMS';
 const types=[...new Set(profile.certifications.map(certificationType))],group=$('.cert-toolbar [role="group"]'),signature=types.join('|');
 if(group.dataset.issuers!==signature){group.dataset.issuers=signature;group.innerHTML=['All',...types].map(type=>{const cert=profile.certifications.find(c=>certificationType(c)===type);const label=type==='All'?'All':type==='nptel'?'NPTEL':type==='hr'?'HackerRank':cert.issuer||cert.type||'Other';return `<button data-cert-filter="${esc(type)}" aria-pressed="false">${esc(label)}</button>`;}).join('');}
 const list=profile.certifications.filter(c=>certFilter==='All'||certificationType(c).startsWith(certFilter));
 $('#cert-grid').innerHTML=list.map(c=>{
 const original=window.PROFILE_VISUALS.certificates[c.asset]||{accent:c.color||'#8b5cff',icon:icon(c.icon||'award'),titleSize:c.titleSize||32,issuerIcon:icon('badge-check')};const i=profile.certifications.indexOf(c),n=certificationType(c)==='nptel',title=c.title.split(',')[0],credential=credentialIdentity(c);
 if(n)return `<button class="cert-card nptel" data-cert="${i}" data-credential="${esc(c.asset||'custom-'+i)}" style="--cert-color:${original.accent};--credential-title-size:${original.titleSize}" aria-label="View and verify ${esc(title)}"><span class="nptel-emblem"><span class="credential-rosette"></span><span class="credential-ribbon ribbon-left"></span><span class="credential-ribbon ribbon-right"></span><span class="credential-gold-ring"></span><span class="credential-disc"></span>${original.icon}<strong>NPTEL</strong><span class="credential-shine"></span></span><span class="nptel-copy"><span class="credential-verified">${icon('badge-check')} VERIFIED</span><span class="nptel-issuer">${esc(c.issuer||'NPTEL · IIT KHARAGPUR')}</span><h3>${esc(title)}</h3><span class="nptel-course-tags"><span>${icon('clock')} ${esc(c.weeks||(i===0?'12':'8'))}-WEEK COURSE</span><span>${icon('calendar-days')} ${esc(c.period||(i===0?'JUL–OCT 2023':'JAN–MAR 2024'))}</span></span><span class="nptel-id"><small>CERTIFICATE ID</small><span class="credential-number">${esc(credential)}</span></span><span class="nptel-status"><span>${icon('badge-check')} SUCCESSFULLY COMPLETED</span><b>VERIFY ${icon('arrow-up-right')}</b></span></span></button>`;
 let level=c.level||title.match(/\(([^)]+)\)/)?.[1]||(certificationType(c)==='hr'?'Basic':'Completed');let name=title.replace(/\s*\([^)]*\)/,'');const color=original.accent;const skill=name.startsWith('Problem')?'puzzle':name.startsWith('SQL')?'database':name.startsWith('Python')?'code-xml':name.startsWith('JavaScript')?'braces':'palette';let dots=level==='Advanced'?3:level==='Intermediate'?2:1;
 return `<button class="cert-card" data-cert="${i}" data-credential="${esc(c.asset||'custom-'+i)}" style="--cert-color:${color}" aria-label="View and verify ${esc(title)}"><span class="cert-top"><span class="issuer-name">${original.issuerIcon} ${esc(c.issuer||(certificationType(c)==='hr'?'HACKERRANK':'CERTIFICATE'))}</span><small>${esc(c.period||(certificationType(c)==='hr'?'JUL 2023':'ISSUER CREDENTIAL'))}</small></span><span class="badge-symbol" style="--badge-color:${color}"><span class="hex-outer"></span><span class="hex-inner"></span>${original.icon}<span class="credential-shine"></span></span><h3>${esc(name)}</h3><span class="cert-level">${esc(level.toUpperCase())}<span>${[0,1,2].map(d=>`<i class="${d<dots?'filled':''}"></i>`).join('')}</span></span><span class="cert-bottom"><span>ID ${esc(credential)}</span><b>VERIFY ${icon('arrow-up-right')}</b></span></button>`;
 }).join('');
 $$('[data-cert-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.certFilter===certFilter);b.setAttribute('aria-pressed',b.dataset.certFilter===certFilter);});icons();
}

function showCert(i){let c=profile.certifications[i];if(!c)return;let id=credentialIdentity(c);dialog('CREDENTIAL / ORIGINAL VERIFICATION LINK',`<h2>${esc(c.title.split(',')[0])}</h2><p>${esc(c.title)}</p><p>Verification is provided by the original issuing platform. This portfolio links to the public verification page; it does not perform independent credential verification.</p><div class="verify-id">CREDENTIAL ID<br>${esc(id)}</div><div class="dialog-actions">${link(c.url,'Verify on issuer’s website')}<button data-copy="${esc(c.url)}">Copy verification link</button></div>`);}
async function copy(value){try{await navigator.clipboard.writeText(value);toast('Copied to clipboard.');}catch{dialog('COPY THIS TEXT',`<p>Select and copy the text below:</p><div class="verify-id" style="user-select:all">${esc(value)}</div>`);}}
async function api(path){const c=new AbortController(),t=setTimeout(()=>c.abort(),12000);try{const r=await fetch('https://api.github.com/'+path,{signal:c.signal,headers:{Accept:'application/vnd.github+json'}});if(!r.ok)throw Error(r.status===403||r.status===429?'GitHub API rate limit reached':`GitHub API returned ${r.status}`);return await r.json();}finally{clearTimeout(t);}}
function applyGithub(data,label){github=data;$('#hero-repos').textContent=data.user.public_repos+' repos';$('#github-count').textContent=data.user.public_repos+' public repos · '+data.user.followers+' followers';
 let strip=$('.github-strip'),langBox=strip.querySelector('.github-mini-langs');if(!langBox){langBox=document.createElement('span');langBox.className='github-mini-langs';strip.insertBefore(langBox,strip.lastElementChild);}const languageCounts=languages(),denom=languageCounts.reduce((sum,r)=>sum+r[1],0)||1;langBox.innerHTML=languageCounts.slice(0,4).map(([l,n])=>`<span title="Share of primary languages across owned non-fork public repos"><i style="background:${langColors[l]||'#8b9bc0'}"></i>${esc(l==='Jupyter Notebook'?'Jupyter':l)} ${Math.round(n/denom*100)}%</span>`).join('');$('#data-status').textContent=label;renderProjects();renderStats();}
async function refreshGithub(force=false){if(force&&Date.now()-lastRefresh<60000){toast('Please wait one minute before refreshing again.');return;}lastRefresh=Date.now();$('#github-refresh').disabled=true;try{const user=await api('users/'+profile.username);let repos=[],page=1;while(true){let batch=await api(`users/${profile.username}/repos?per_page=100&type=owner&sort=updated&page=${page++}`);repos.push(...batch);if(batch.length<100)break;}const data={user,repos,updatedAt:new Date().toISOString()};try{localStorage.setItem('ayush-native-github',JSON.stringify({saved:Date.now(),data}));}catch{}applyGithub(data,'GITHUB LIVE · '+new Date().toLocaleString()+' / '+lcStatusLabel());if(force)toast('Public GitHub data refreshed.');}catch(e){$('#data-status').textContent=`SAVED GITHUB SNAPSHOT · ${github?.updatedAt||'unavailable'} / ${e.name==='AbortError'?'Request timed out':e.message}. / ${lcStatusLabel()}`;if(force)toast('Could not refresh. Saved data remains visible.');}finally{$('#github-refresh').disabled=false;}}
const sectionNames=[['top','Introduction'],['about','About / Beyond the code'],['stack','Tech stack'],['projects','Projects'],['journey','Journey'],['stats','Stats / GitHub and LeetCode'],['achievements','Badges & awards'],['certs','Certifications'],['connect','Contact / Résumé']];
function renderCommands(){const q=$('#command-search').value.toLowerCase();$('#command-results').innerHTML=sectionNames.filter(x=>x[1].toLowerCase().includes(q)).map(([id,label])=>`<a href="#${id}" data-command-result>${label}<span>↵</span></a>`).join('')||'<p class="subline">No matching sections.</p>';}
function openCommands(){renderCommands();$('#command-dialog').showModal();$('#command-search').focus();}
let gameCells=Array(9).fill(''),gameTurn='X',calcExpression='',tasks=[];
try{const saved=JSON.parse(localStorage.getItem('ayush-demo-tasks'));if(Array.isArray(saved))tasks=saved.filter(t=>typeof t.text==='string'&&typeof t.done==='boolean').slice(0,100);}catch{}
function openLab(id){
 if(id===6){dialog('INTERACTIVE MINI DEMO / LOCAL QR GENERATOR',`<h2>CREATE A QR CODE.</h2><p>Generate a real QR code locally in your browser. No text is sent to a server. This is a small portfolio demo, not the original Android scanner.</p><label class="lab-field">Text or URL<input id="qr-text" maxlength="500" value="https://github.com/Ayushkathoke" aria-label="QR code text"></label><div class="dialog-actions"><button data-qr-generate>Generate QR code</button>${link(profile.projects[6].url,'Original project source')}</div><div id="qr-result" class="qr-result" aria-live="polite"></div>`);generateQR();}
 else if(id===12){dialog('INTERACTIVE MINI DEMO / TWO-PLAYER LOCAL GAME',`<h2>TIC-TAC-TOE.</h2><p>A working two-player game in this portfolio. Take turns as X and O on the same device.</p><div id="game-status" class="game-status" role="status"></div><div id="game-board" class="game-board"></div><div class="dialog-actions"><button data-game-reset>New game</button>${link(profile.projects[12].url,'Original Android app source')}</div>`);renderGame();}
 else if(id===13){dialog('INTERACTIVE MINI DEMO / NATIVE JAVASCRIPT',`<h2>EASY CALCULATOR.</h2><p>A real local calculator for +, −, ×, ÷ and parentheses. Parsed safely without eval. This is not the original Android app.</p><input id="calc-display" class="calc-display" value="${esc(calcExpression)}" placeholder="0" aria-label="Calculator expression"><div class="calc-keys">${['C','(',')','⌫','7','8','9','/','4','5','6','*','1','2','3','-','0','.','=','+'].map(k=>`<button data-calc="${k}" class="${k==='='?'equals':''}">${k==='*'?'×':k==='/'?'÷':k}</button>`).join('')}</div><p id="calc-error" role="status"></p><div class="dialog-actions">${link(profile.projects[13].url,'Original project source')}</div>`);}
 else{const p=profile.projects[id];dialog('INTERACTIVE MINI DEMO / LOCAL TASK LIST',`<h2>${esc(p.title)}</h2><p>A working task-list demo. Your tasks stay in this browser’s local storage. No reminders, server sync or account are created by this preview.</p><div class="task-input"><input id="new-task" maxlength="150" placeholder="What do you want to build?" aria-label="New task"><button data-add-task>Add task</button></div><div id="task-list" aria-live="polite"></div><div class="dialog-actions">${link(p.url,'Open original project')}</div>`);renderTaskList();}
}
function generateQR(){const text=$('#qr-text')?.value.trim();if(!text){$('#qr-result').textContent='Enter text or a URL first.';return;}try{const qr=qrcode(0,'M');qr.addData(text);qr.make();$('#qr-result').innerHTML=qr.createImgTag(5,16,'Generated QR code')+'<p>Scan with your phone camera.</p>';}catch{$('#qr-result').textContent='Could not generate this QR code. Try shorter text.';}}
function winner(){for(const [a,b,c]of[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]])if(gameCells[a]&&gameCells[a]===gameCells[b]&&gameCells[a]===gameCells[c])return gameCells[a];return '';}
function renderGame(){const win=winner(),draw=!win&&gameCells.every(Boolean);$('#game-status').textContent=win?win+' wins!':draw?'It’s a draw. Start a new game.':gameTurn+' to play';$('#game-board').innerHTML=gameCells.map((v,i)=>`<button data-game-cell="${i}" ${v||win||draw?'disabled':''} aria-label="Cell ${i+1}, ${v||'empty'}" class="${v==='X'?'x-mark':'o-mark'}">${v}</button>`).join('');}
function playCell(i){if(gameCells[i]||winner())return;gameCells[i]=gameTurn;gameTurn=gameTurn==='X'?'O':'X';renderGame();}
function evaluateArithmetic(expr){const stripped=expr.replace(/\s/g,'');const tokens=stripped.match(/\d+(?:\.\d*)?|\.\d+|[()+\-*/]/g)||[];if(!stripped||tokens.join('')!==stripped)throw Error('Use numbers, parentheses and + − × ÷ only.');let i=0;function factor(){let t=tokens[i++];if(t==='+')return factor();if(t==='-')return-factor();if(t==='('){let n=expression();if(tokens[i++]!==')')throw Error('Check the parentheses.');return n;}if(t===undefined||!/^\d|^\./.test(t))throw Error('Complete the expression first.');return Number(t);}function term(){let n=factor();while(tokens[i]==='*'||tokens[i]==='/'){let op=tokens[i++],r=factor();n=op==='*'?n*r:n/r;}return n;}function expression(){let n=term();while(tokens[i]==='+'||tokens[i]==='-'){let op=tokens[i++],r=term();n=op==='+'?n+r:n-r;}return n;}const result=expression();if(i!==tokens.length)throw Error('Check the expression.');if(!Number.isFinite(result))throw Error('The result is not finite. Check division by zero.');return Number(result.toPrecision(12));}
function calculator(key){calcExpression=$('#calc-display').value;$('#calc-error').textContent='';if(key==='C')calcExpression='';else if(key==='⌫')calcExpression=calcExpression.slice(0,-1);else if(key==='='){try{calcExpression=String(evaluateArithmetic(calcExpression));}catch(e){$('#calc-error').textContent=e.message;}}else if(calcExpression.length<100)calcExpression+=key;$('#calc-display').value=calcExpression;}
function saveTasks(){try{localStorage.setItem('ayush-demo-tasks',JSON.stringify(tasks));}catch{toast('Browser storage unavailable. Tasks last only for this page session.');}}
function renderTaskList(){$('#task-list').innerHTML=tasks.length?tasks.map((t,i)=>`<div class="local-task"><button data-toggle-task="${i}" aria-label="${t.done?'Mark incomplete':'Mark complete'}" aria-pressed="${t.done}">${t.done?'✓':'○'}</button><span class="${t.done?'done':''}">${esc(t.text)}</span><button data-delete-task="${i}" aria-label="Delete task">×</button></div>`).join(''):'<p>No tasks yet. Add your first idea.</p>';}
function addTask(){const text=$('#new-task').value.trim();if(!text)return;if(tasks.length>=100){toast('The demo supports up to 100 tasks.');return;}tasks.push({text,done:false});$('#new-task').value='';saveTasks();renderTaskList();}

function wire(){
 document.addEventListener('click',e=>{let b=e.target.closest('[data-terminal]');if(b)terminal(+b.dataset.terminal);b=e.target.closest('[data-beyond]');if(b)beyond(+b.dataset.beyond);b=e.target.closest('[data-stack]');if(b)showTech(b.dataset.stack);b=e.target.closest('[data-project-open]');if(b)showProject(b.dataset.projectOpen);b=e.target.closest('[data-lab]');if(b)openLab(+b.dataset.lab);b=e.target.closest('[data-qr-generate]');if(b)generateQR();b=e.target.closest('[data-game-cell]');if(b)playCell(+b.dataset.gameCell);b=e.target.closest('[data-game-reset]');if(b){gameCells=Array(9).fill('');gameTurn='X';openLab(12);}b=e.target.closest('[data-calc]');if(b)calculator(b.dataset.calc);b=e.target.closest('[data-add-task]');if(b)addTask();b=e.target.closest('[data-toggle-task]');if(b){tasks[+b.dataset.toggleTask].done=!tasks[+b.dataset.toggleTask].done;saveTasks();renderTaskList();}b=e.target.closest('[data-delete-task]');if(b){tasks.splice(+b.dataset.deleteTask,1);saveTasks();renderTaskList();}b=e.target.closest('[data-filter]');if(b){projectFilter=b.dataset.filter;renderProjects();}b=e.target.closest('[data-filter-shortcut]');if(b){projectFilter=b.dataset.filterShortcut;renderProjects();location.hash='projects';}b=e.target.closest('[data-year]');if(b){journey(+b.dataset.year);$('#journey-detail').classList.add('expanded');}b=e.target.closest('[data-stats-tab]');if(b){statsTab=b.dataset.statsTab;$('#topic-search').value='';renderStats();}b=e.target.closest('[data-stat-detail]');if(b)statDetail(b.dataset.statDetail,+b.dataset.value);b=e.target.closest('[data-topic]');if(b){let topic=b.dataset.topic;dialog('LEETCODE / TOPIC SNAPSHOT',`<h2>${esc(topic)}</h2><p>${profile.leetcode.topics[topic]} solved questions are tagged ${esc(topic)} in the saved LeetCode dataset. A question can have multiple tags; topic counts do not sum to the total solved.</p><div class="dialog-actions">${link('https://leetcode.com/u/ayushkathoke/','View coding profile')}</div>`);}b=e.target.closest('[data-award]');if(b){const a=awards[+b.dataset.award];dialog('PROOF OF WORK / PROFILE CLAIM',`<h2>${esc(a[0])}</h2><p>${a[1]}</p><p>Imported from the original GitHub profile. These are editorial achievements; this website does not independently verify awards or update badge counts.</p>${a[3]!==null?`<div class="dialog-actions">${link(codingProfiles[a[3]][1],'View platform profile')}</div>`:''}`);}b=e.target.closest('[data-cert-filter]');if(b){certFilter=b.dataset.certFilter;renderCerts();}b=e.target.closest('[data-cert]');if(b)showCert(+b.dataset.cert);b=e.target.closest('[data-copy]');if(b)copy(b.dataset.copy);b=e.target.closest('[data-command-result]');if(b)$('#command-dialog').close();b=e.target.closest('[data-explain-snapshot]');if(b)dialog('ABOUT THE CODING VISUAL',`<h2>${profile.leetcode.activeDays} ACTIVE DAYS.</h2><p>${esc(lcProvenance())} The colored grid is an illustration, not a daily contribution calendar. No daily activity has been invented.</p><div class="dialog-actions">${link(codingProfiles[0][1],'View actual coding profile')}</div>`);
 });
 $('#stack-search').addEventListener('input',renderStack);$('#project-search').addEventListener('input',renderProjects);$('#project-sort').addEventListener('change',renderProjects);$('#topic-search').addEventListener('input',renderTopics);$('#copy-email').addEventListener('click',()=>copy(profile.email));$('#github-refresh').addEventListener('click',()=>refreshGithub(true));$('#role-cycle').addEventListener('click',()=>{roleIndex=(roleIndex+1)%roleLabels.length;$('#role-text').textContent=roleLabels[roleIndex];});
 const portraitFiles={hero:'hero-44.webp',about:'about-34.webp',dashboard:'dashboard-56.webp'};$$('[data-portrait]').forEach(b=>b.addEventListener('click',()=>{$('#hero-photo').src=imageURL(portraitFiles[b.dataset.portrait]);$('#hero-photo').classList.toggle('headshot',b.dataset.portrait==='dashboard');$$('[data-portrait]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});}));
 $('#education').addEventListener('click',()=>dialog('EDUCATION / CLASS OF 2025','<h2>B.TECH / INFORMATION TECHNOLOGY</h2><p>J D College of Engineering & Management, Nagpur.</p><div class="detail-list"><div><b>2021–2025</b>Undergraduate journey</div><div><b>84.9%</b>Graduation result</div></div><p>Details imported from the original profile.</p>'));
 $('#close-dialog').addEventListener('click',()=>$('#detail-dialog').close());$('#close-command').addEventListener('click',()=>$('#command-dialog').close());$('#command-button').addEventListener('click',openCommands);$('#command-search').addEventListener('input',renderCommands);
 $$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
 document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='new-task'){e.preventDefault();addTask();return;}if(e.key==='Enter'&&e.target.id==='qr-text'){e.preventDefault();generateQR();return;}if(e.key==='Enter'&&e.target.id==='calc-display'){e.preventDefault();calculator('=');return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#command-dialog').open)$('#command-dialog').close();else openCommands();}});
 // Native tab arrow-key navigation is shared by all component tablists.
 $$('[role="tablist"]').forEach(group=>group.addEventListener('keydown',e=>{const buttons=[...group.querySelectorAll('[role="tab"]')];if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;let i=buttons.indexOf(document.activeElement);if(i<0)return;e.preventDefault();let next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();buttons[next].click();}));
 $('#theme-toggle').addEventListener('click',()=>{const light=document.body.classList.toggle('light');$('#theme-toggle').setAttribute('aria-label',light?'Switch to dark theme':'Switch to light theme');try{localStorage.setItem('ayush-native-theme',light?'light':'dark');}catch{}renderStats();});
 if('IntersectionObserver'in window){const ob=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)$$('.navigation nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));});},{rootMargin:'-10% 0px -65% 0px'});$$('section[id]').forEach(s=>ob.observe(s));}
}
async function init(){icons();$('#year').textContent=new Date().getFullYear();try{if(localStorage.getItem('ayush-native-theme')==='light')document.body.classList.add('light');}catch{}
 try{const load=async url=>{const r=await fetch(url);if(!r.ok)throw Error(url+' unavailable');return r.json();};const [p,g]=window.__BUNDLED_DATA__?[window.__BUNDLED_DATA__.profile,window.__BUNDLED_DATA__.github]:await Promise.all([load('data/profile.json'),load('data/github.json')]);profile=p;github=g;syncLeetcode();terminal(0);beyond(0);renderOrbit();renderStack();renderJourney();renderAwards();renderCerts();wire();let cache;try{cache=JSON.parse(localStorage.getItem('ayush-native-github'));}catch{}if(cache&&Date.now()-cache.saved<15*60*1000)applyGithub(cache.data,'GITHUB CACHED · '+date(cache.data.updatedAt)+' / '+lcStatusLabel());else{applyGithub(g,'GITHUB SAVED SNAPSHOT · '+g.updatedAt+' / '+lcStatusLabel());refreshGithub();}icons();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)setInterval(()=>{if(!document.hidden&&!document.body.classList.contains('motion-paused')&&!matchMedia('(prefers-reduced-motion: reduce)').matches){roleIndex=(roleIndex+1)%roleLabels.length;$('#role-text').textContent=roleLabels[roleIndex];}},3200);
 }catch(e){$('#data-status').textContent='Could not load local profile data. Open this site using an HTTP server; see README.md.';toast('Profile data unavailable. Please reload or use a web server.');console.error(e);}}
init();
